"""Independent, literal reference model of PROTOCOL.md (slow, small cases only)."""
import struct, sys, zlib, hashlib
sys.path.insert(0, '/workspace/project')
import wire
MASK = (1 << 24) - 1
NAMES = wire.NAMES


def icrc(frame):
    ip_len = int.from_bytes(frame[16:18], 'big')
    buf = bytearray(b'\xff' * 8 + frame[14:14 + ip_len - 4])
    buf[9] = 255
    buf[16] = 255
    buf[18:20] = b'\xff\xff'
    buf[34:36] = b'\xff\xff'
    buf[40] = 255
    return struct.pack('<I', zlib.crc32(bytes(buf)))


def payload_words(seed, p, rank, d):
    return [(seed + 0x9e3779b9 * (p + 1) + 0x85ebca6b * (rank + 1) + 0xc2b2ae35 * (j + 1)) & 0xffffffff
            for j in range(d)]


def parse(frame, plen):
    """Wire validity only. Returns ('data',psn,payload) | ('ack',psn) | None."""
    if len(frame) < 58:
        return None
    if frame[12:14] != b'\x08\x00':
        return None
    ip = frame[14:]
    ip_len = int.from_bytes(ip[2:4], 'big')
    if ip_len + 14 != len(frame):
        return None
    if ip[0] != 0x45 or ip[9] != 17:
        return None
    s = sum(int.from_bytes(ip[i:i + 2], 'big') for i in range(0, 20, 2))
    while s >> 16:
        s = (s & 0xffff) + (s >> 16)
    if (s & 0xffff) != 0xffff:
        return None
    if int.from_bytes(ip[6:8], 'big') not in (0, 0x4000):
        return None
    udp = ip[20:]
    udp_len = int.from_bytes(udp[4:6], 'big')
    if udp_len != ip_len - 20 or udp_len < 24:
        return None
    if udp[0:4] != b'\x12\xb7\x12\xb7' or udp[6:8] != b'\x00\x00':
        return None
    bth = udp[8:]
    if bth[1] != 0 or bth[2:4] != b'\xff\xff' or bth[4] != 0:
        return None
    psn = int.from_bytes(bth[9:12], 'big')
    if bth[0] == 0x04:
        if bth[8] != 0x80 or udp_len != 24 + plen:
            return None
        kind, body = 'data', bth[12:12 + plen]
    elif bth[0] == 0x11:
        if bth[8] != 0x00 or udp_len != 28 or bth[12] != 0x1f:
            return None
        if int.from_bytes(bth[13:16], 'big') != ((psn + 1) & MASK):
            return None
        kind, body = 'ack', None
    else:
        return None
    if icrc(frame) != frame[-4:]:
        return None
    return (kind, psn, body)


def endpoint(frame, rank, kind, psn, pr, root, K, start):
    if frame[0:6] != bytes((2, 1, 0, 0, 0, rank + 1)):
        return False
    if frame[6:12] != bytes((2, 0, 0, 0, 0, rank + 1)):
        return False
    if frame[26:30] != bytes((10, 0, 0, rank + 1)):
        return False
    if frame[30:34] != bytes((10, 0, 0, 101 + rank)):
        return False
    qpn = int.from_bytes(frame[42:46], 'big')
    if qpn != 0x200 + rank:
        return False
    if kind == 'data':
        if pr == 'broadcast' and rank != root:
            return False
        if (psn - start) % (1 << 24) >= K:
            return False
    return True


def ord_of(d, s):
    return len([r for r in range(0, s) if r != d])


def rank_of_ord(d, o):
    return [r for r in range(4) if r != d][o]


class Ref:
    def __init__(self, primitive, mode, root, K, D, N, start, trace):
        self.pr, self.mode, self.root = primitive, mode, root
        self.K, self.D, self.N, self.start, self.trace = K, D, N, start, trace
        self.plen = 4 * D
        self.b = 0
        self.slots = {}
        self.R = [0] * 4
        self.E = [0] * 4
        self.U = [0] * 4
        self.S = [0] * 4
        self.acked = [0] * 4
        self.repeat = [False] * 4
        self.occupied = 0
        self.c = dict(rx_data=0, rx_ack=0, tx_data=0, tx_ack=0, accepted=0, dup=0, blocked=0,
                      stale=0, wire=0, endpoint=0, ack_ignored=0, failed=0, overwrite=0)
        self.budget = -1
        self.h = hashlib.sha256()
        self.packets = 0
        self.nbytes = 0
        self.trace_frames = []
        self.snaps = []

    # ---- helpers -----------------------------------------------------------
    def need_mask(self):
        return (1 << self.root) if self.pr == 'broadcast' else 0x0f

    def sources(self):
        return [self.root] if self.pr == 'broadcast' else [0, 1, 2, 3]

    def out_limit(self, d):
        if self.pr == 'allreduce':
            return self.K
        if self.pr == 'reduce':
            return self.K if d == self.root else 0
        if self.pr == 'broadcast':
            return 0 if d == self.root else self.K
        if self.pr == 'barrier':
            return 1
        if self.pr == 'allgather':
            return 3 * self.K
        return self.K // 4

    def out_map(self, d, q):
        """(p, src) or None."""
        if self.pr in ('allreduce', 'reduce', 'broadcast'):
            if self.pr == 'reduce' and d != self.root:
                return None
            if self.pr == 'broadcast' and d == self.root:
                return None
            return (q, -1) if q < self.K else None
        if self.pr == 'barrier':
            return (0, -1) if q == 0 else None
        if self.pr == 'allgather':
            p, o = q // 3, q % 3
            return (p, rank_of_ord(d, o)) if p < self.K else None
        p = d * (self.K // 4) + q
        return (p, -1) if p < self.K else None

    def ready(self, d, q):
        m = self.out_map(d, q)
        if m is None:
            return False
        slot = self.slots.get(m[0])
        return bool(slot and slot['complete'])

    # ---- transcript --------------------------------------------------------
    def emit(self, rank, frame, ack):
        if self.budget == 0:
            self.c['failed'] += 1
            return False
        if self.budget > 0:
            self.budget -= 1
        self.h.update(bytes((rank,)) + struct.pack('<I', len(frame)) + frame)
        self.packets += 1
        self.nbytes += len(frame)
        self.c['tx_ack' if ack else 'tx_data'] += 1
        if len(self.trace_frames) < self.trace:
            self.trace_frames.append({'rank': rank, 'hex': frame.hex()})
        return True

    def send_up_ack(self, rank, prefix):
        frame = wire.packet(rank, (self.start + prefix - 1) & MASK, ack=True)
        return self.emit(rank, frame, True)

    def send_result(self, d, q):
        m = self.out_map(d, q)
        slot = self.slots[m[0]]
        p, src = m
        psn = (self.start + q) & MASK
        if self.pr == 'allgather':
            body = slot['gather'][src]
        elif self.pr == 'broadcast':
            body = slot['raw']
        elif self.pr == 'barrier':
            body = b''
        else:
            body = struct.pack('<%dI' % self.D, *slot['accum'])
        frame = wire.packet(d, psn, body, outgoing=True)
        return self.emit(d, frame, False)

    # ---- eligibility -------------------------------------------------------
    def safe(self, r, p):
        if self.mode == 3:
            return True
        if self.pr in ('allreduce', 'barrier'):
            return self.acked[r] > p
        if self.pr == 'reduce':
            return self.acked[self.root] > p
        if self.pr == 'broadcast':
            return all(self.acked[d] > p for d in range(4) if d != self.root)
        if self.pr == 'reducescatter':
            return self.acked[p // (self.K // 4)] > p % (self.K // 4)
        return all(self.acked[d] > 3 * p + ord_of(d, r) for d in range(4) if d != r)

    def extend(self, r):
        if self.mode == 3:
            self.E[r] = self.R[r]
            return
        while self.E[r] < self.R[r] and self.safe(r, self.E[r]):
            self.E[r] += 1

    def outs_acked(self, p):
        if self.pr == 'allreduce':
            return all(self.acked[d] > p for d in range(4))
        if self.pr == 'reduce':
            return self.acked[self.root] > p
        if self.pr == 'broadcast':
            return all(self.acked[d] > p for d in range(4) if d != self.root)
        if self.pr == 'barrier':
            return all(self.acked[d] >= 1 for d in range(4))
        if self.pr == 'allgather':
            return all(self.acked[d] >= 3 * p + 3 for d in range(4))
        return self.acked[p // (self.K // 4)] > p % (self.K // 4)

    def retire(self):
        while self.b < self.K:
            slot = self.slots.get(self.b)
            if not slot or not slot['complete']:
                return
            if not self.outs_acked(self.b):
                return
            if not all(self.U[r] > self.b for r in self.sources()):
                return
            del self.slots[self.b]
            self.occupied -= 1
            self.b += 1

    def service(self, is_retry=False, retry_rank=-1):
        for r in range(4):
            self.extend(r)
        for r in range(4):
            if self.E[r] == 0 or (not self.repeat[r] and self.E[r] <= self.U[r]):
                continue
            if not self.send_up_ack(r, self.E[r]):
                self.retire()
                return
            self.U[r] = self.E[r]
            self.repeat[r] = False
        if is_retry:
            q = self.acked[retry_rank]
            while q < self.S[retry_rank]:
                if not self.ready(retry_rank, q):
                    break
                if not self.send_result(retry_rank, q):
                    self.retire()
                    return
                q += 1
        for d in range(4):
            while self.S[d] < self.out_limit(d):
                if not self.ready(d, self.S[d]):
                    break
                if not self.send_result(d, self.S[d]):
                    self.retire()
                    return
                self.S[d] += 1
        self.retire()

    # ---- ingress -----------------------------------------------------------
    def ingress(self, rank, frame):
        got = parse(frame, self.plen)
        if got is None:
            self.c['wire'] += 1
            return
        kind, psn, body = got
        if not endpoint(frame, rank, kind, psn, self.pr, self.root, self.K, self.start):
            self.c['endpoint'] += 1
            return
        if kind == 'ack':
            self.c['rx_ack'] += 1
            prefix = (psn - self.start + 1) % (1 << 24)
            if prefix > self.acked[rank] and prefix <= self.S[rank]:
                self.acked[rank] = prefix
            else:
                self.c['ack_ignored'] += 1
        else:
            self.c['rx_data'] += 1
            p = (psn - self.start) % (1 << 24)
            if p < self.b:
                self.c['stale'] += 1
                self.repeat[rank] = True
            elif p >= self.b + self.N:
                self.c['blocked'] += 1
            else:
                slot = self.slots.get(p)
                if slot is None:
                    slot = {'mask': 0, 'complete': 0, 'gather': [None] * 4, 'raw': None,
                            'accum': [0] * self.D}
                    self.slots[p] = slot
                    self.occupied += 1
                bit = 1 << rank
                if slot['mask'] & bit:
                    self.c['dup'] += 1
                    self.repeat[rank] = True
                else:
                    if self.pr == 'allgather':
                        slot['gather'][rank] = bytes(body)
                    elif self.pr == 'broadcast':
                        slot['raw'] = bytes(body)
                    elif self.pr == 'barrier':
                        pass
                    else:
                        words = list(struct.unpack('!%dI' % self.D, body))
                        if slot['mask'] == 0:
                            slot['accum'] = words
                        else:
                            slot['accum'] = [(a + w) & 0xffffffff for a, w in zip(slot['accum'], words)]
                    slot['mask'] |= bit
                    slot['complete'] = 1 if slot['mask'] == self.need_mask() else 0
                    self.c['accepted'] += 1
                    if p == self.R[rank]:
                        while self.R[rank] < self.K:
                            nxt = self.slots.get(self.R[rank])
                            if not nxt or not (nxt['mask'] & bit):
                                break
                            self.R[rank] += 1
        self.service()

    # ---- certificate -------------------------------------------------------
    def digest(self):
        h = 14695981039346656037
        fold = lambda x: ((h := (h ^ x) * 1099511628211) and 0)  # noqa
        for p in sorted(self.slots):
            slot = self.slots[p]
            for i in range(8):
                h = ((h ^ ((p >> (8 * i)) & 0xff)) * 1099511628211) & 0xffffffffffffffff
            for byte in (slot['mask'], slot['complete']):
                h = ((h ^ byte) * 1099511628211) & 0xffffffffffffffff
            if self.pr == 'allgather':
                for r in range(4):
                    h = ((h ^ (1 if slot['gather'][r] is not None else 0)) * 1099511628211) & 0xffffffffffffffff
                    if slot['gather'][r] is not None:
                        for byte in slot['gather'][r]:
                            h = ((h ^ byte) * 1099511628211) & 0xffffffffffffffff
            elif self.pr == 'broadcast':
                for byte in slot['raw']:
                    h = ((h ^ byte) * 1099511628211) & 0xffffffffffffffff
            else:
                for w in slot['accum']:
                    for i in range(4):
                        h = ((h ^ ((w >> (8 * i)) & 0xff)) * 1099511628211) & 0xffffffffffffffff
        return h

    def state(self):
        st = [0] * 32
        st[0] = self.b
        st[1] = self.occupied
        st[2:6] = self.R
        st[6:10] = self.S
        st[10:14] = self.acked
        st[14:18] = self.U
        st[18] = self.c['rx_data']
        st[19] = self.c['rx_ack']
        st[20] = self.c['tx_data']
        st[21] = self.c['tx_ack']
        st[22] = self.c['accepted']
        st[23] = self.c['dup']
        st[24] = self.c['blocked']
        st[25] = self.c['stale']
        st[26] = self.c['wire']
        st[27] = self.c['endpoint']
        st[28] = self.c['ack_ignored']
        st[29] = self.c['failed']
        st[30] = self.c['overwrite']
        st[31] = 0
        return st

    def snapshot(self):
        return {'state': self.state(), 'buffer': format(self.digest(), '016x'),
                'wire_sha256': self.h.hexdigest(), 'packets': self.packets, 'bytes': self.nbytes}

    # ---- events ------------------------------------------------------------
    def gen_data(self, rank, p, seed=0, values=None, xor=()):
        body = struct.pack('!%dI' % len(values), *values) if values is not None else \
            struct.pack('!%dI' % self.D, *payload_words(seed, p, rank, self.D))
        frame = bytearray(wire.packet(rank, (self.start + p) & MASK, body))
        for offset, byte in xor:
            frame[offset] ^= byte
        self.ingress(rank, bytes(frame))

    def gen_ack(self, rank, upto):
        self.ingress(rank, wire.packet(rank, (self.start + upto - 1) & MASK, ack=True))

    def run_train(self, p, count, width, ranks, reverse=False, seed=0):
        end = p + count
        lo = p
        while lo < end:
            hi = min(end, lo + width)
            for r in ranks:
                if self.pr == 'broadcast' and r != self.root:
                    continue
                seq = range(hi - 1, lo - 1, -1) if reverse else range(lo, hi)
                for pp in seq:
                    self.gen_data(r, pp, seed)
            for r in range(4):
                if self.pr == 'allgather':
                    n = 3 * hi
                elif self.pr == 'reducescatter':
                    n = max(0, min(self.K // 4, hi - r * (self.K // 4)))
                else:
                    recv = (self.pr != 'reduce' or r == self.root) and \
                           (self.pr != 'broadcast' or r != self.root)
                    n = hi if recv else 0
                self.gen_ack(r, n)
            lo += width

    def run(self, events):
        for op in events:
            name = op['op']
            if name == 'data':
                for i in range(op.get('count', 1)):
                    self.gen_data(op['rank'], op['p'] + i * op.get('step', 1), op.get('seed', 0),
                                  op.get('values'), op.get('xor', []))
            elif name == 'ack':
                self.gen_ack(op['rank'], op['upto'])
            elif name == 'wire':
                self.ingress(op['rank'], bytes.fromhex(op['hex']))
            elif name == 'budget':
                self.budget = op['n']
            elif name == 'flush':
                self.service()
            elif name == 'retry':
                self.repeat[op['rank']] = True
                self.service(True, op['rank'])
            elif name == 'snap':
                self.snaps.append(dict(self.snapshot(), tag=op['tag']))
            elif name == 'train':
                self.run_train(op['p'], op['count'], op['width'], op['ranks'],
                               op.get('reverse', False), op.get('seed', 0))
        return self.snapshot()


def solve_case(case):
    ref = Ref(case['primitive'], case['mode'], case['root'], case['segments'], case['words'],
              case['capacity'], case['start'], case.get('trace', 0))
    out = ref.run(case['events'])
    out['snapshots'] = ref.snaps
    out['trace'] = ref.trace_frames
    return out
